// 通用 split 函数
vector<int> split(const string& str, const string& delimiter) {
    vector<int> result;
    size_t start = 0;
    size_t end = str.find(delimiter);
    while (end != string::npos) {
        result.push_back(stoi(str.substr(start, end - start)));
        start = end + delimiter.length();
        end = str.find(delimiter, start);
    }
    // 添加最后一个部分
    result.push_back(stoi(str.substr(start)));
    return result;
}
​
int main() {
    string s;
    getline(cin, s);
    vector<int> ans = split(s, " ");
​
    int n = ans.size();
    int minIdx = -1;
    int minValue = INT_MAX;
    // 寻找最小叶子节点下标
    for (int i = n -1; i >= 0; i--) {
        if (ans[i] == -1) {
            continue;
        }
        int leftIndex = 2 * i + 1;
        int rightIndex = 2 * (i+1);
        // 叶子节点
        if ((rightIndex >= n || ans[rightIndex] == -1) && (leftIndex >= n || ans[leftIndex]== -1)) {
            if (ans[i] < minValue) {
                minIdx = i;
                minValue = ans[i];
            }
        }
    }
    // 从最小下标反向到根节点路径节点
    vector<int> res;
    while (minIdx != 0) {
        res.push_back(ans[minIdx]);
        minIdx = (minIdx - 1) /2;
    }
    res.push_back(ans[0]);
    // 输出结果
    for (int i = res.size() -1; i >= 0; i--) {
        cout << res[i];
        if (i != 0) {
            cout << " ";
        }
    }
    return 0;
}

