import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    sc := bufio.NewScanner(os.Stdin)
    sc.Scan()
    line := sc.Text()
​
    // Go 自带 strings.Split + strconv.Atoi
    parts := strings.Fields(line)
    n := len(parts)
    arr := make([]int, n)
    for i, val := range parts {
        arr[i], _ = strconv.Atoi(val)
    }
​
    minIdx := -1
    minVal := 1 << 31 - 1 // INT_MAX
​
    // 寻找最小叶子节点下标
    for i := n - 1; i >= 0; i-- {
        if arr[i] == -1 {
            continue
        }
        left := 2*i + 1
        right := 2*(i + 1)
        if (left >= n || arr[left] == -1) && (right >= n || arr[right] == -1) {
            if arr[i] < minVal {
                minVal = arr[i]
                minIdx = i
            }
        }
    }
​
    // 回溯路径
    res := []int{}
    for minIdx != 0 {
        res = append(res, arr[minIdx])
        minIdx = (minIdx - 1) / 2
    }
    res = append(res, arr[0])
​
    // 反向输出
    for i := len(res) - 1; i >= 0; i-- {
        fmt.Print(res[i])
        if i != 0 {
            fmt.Print(" ")
        }
    }
}
